[CmdletBinding()]param([string]$DatabaseUser=$(if($env:POSTGRES_USER){$env:POSTGRES_USER}else{'dip'}),[string]$DatabaseHost=$(if($env:POSTGRES_HOST){$env:POSTGRES_HOST}else{'127.0.0.1'}),[int]$DatabasePort=$(if($env:POSTGRES_PORT){[int]$env:POSTGRES_PORT}else{5432}),[string]$DatabasePassword=$(if($env:POSTGRES_PASSWORD){$env:POSTGRES_PASSWORD}else{''}))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest;foreach($n in 'psql','pg_dump','pg_restore','git'){if(-not(Get-Command $n -ErrorAction SilentlyContinue)){throw "$n is required."}}
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$out=Join-Path $root 'artifacts\dr-verification';New-Item -Force -ItemType Directory $out|Out-Null;$db='dip_dr_'+[guid]::NewGuid().ToString('N').Substring(0,12);$env:PGPASSWORD=$DatabasePassword
try{
 & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -v ON_ERROR_STOP=1 -c "CREATE DATABASE \"$db\" OWNER \"$DatabaseUser\";" *> $null;if($LASTEXITCODE-ne0){throw 'Temporary DR database create failed.'}
 & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $db -v ON_ERROR_STOP=1 -c "CREATE TABLE dr_probe(id int primary key,value text);INSERT INTO dr_probe VALUES(1,'DIP-DR-PROBE');" *> $null
 $dump=Join-Path $out 'dip-dr.dump';& pg_dump -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $db -Fc -f $dump;& pg_restore --list $dump *> $null
 & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -v ON_ERROR_STOP=1 -c "DROP DATABASE \"$db\";" *> $null; if($LASTEXITCODE-ne0){throw 'Temporary DR database drop failed.'}; & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -v ON_ERROR_STOP=1 -c "CREATE DATABASE \"$db\" OWNER \"$DatabaseUser\";" *> $null; if($LASTEXITCODE-ne0){throw 'Temporary DR database recreate failed.'}; & pg_restore -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $db --no-owner --no-privileges $dump
 $value=(& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $db -At -c 'SELECT value FROM dr_probe WHERE id=1;'|Out-String).Trim();if($value-ne'DIP-DR-PROBE'){throw 'Database restore verification mismatch.'}
 Add-Type -AssemblyName System.IO.Compression.FileSystem;$src=Join-Path $out 'source-artifacts';$dst=Join-Path $out 'restored-artifacts';Remove-Item $src,$dst -Recurse -Force -ErrorAction SilentlyContinue;New-Item -ItemType Directory $src|Out-Null;'artifact-proof'|Set-Content (Join-Path $src 'proof.txt');$zip=Join-Path $out 'artifacts.zip';Remove-Item $zip -Force -ErrorAction SilentlyContinue;[IO.Compression.ZipFile]::CreateFromDirectory($src,$zip);[IO.Compression.ZipFile]::ExtractToDirectory($zip,$dst);if((Get-FileHash (Join-Path $src 'proof.txt') -Algorithm SHA256).Hash-ne(Get-FileHash (Join-Path $dst 'proof.txt') -Algorithm SHA256).Hash){throw 'Artifact restore verification mismatch.'}
 $sha=(& git -C $root rev-parse HEAD|Out-String).Trim();[ordered]@{schema='dip-dr-verification-v3';runtime='native';sourceCommit=$sha;verifiedAtUtc=[DateTimeOffset]::UtcNow.ToString('o');databaseRestore='PASS';artifactRestore='PASS';dumpSha256=(Get-FileHash $dump -Algorithm SHA256).Hash}|ConvertTo-Json|Set-Content (Join-Path $out 'dr-verification.json') -Encoding UTF8;"DR VERIFICATION PASS`nCommit=$sha`nDatabaseRestore=PASS`nArtifactRestore=PASS"|Set-Content (Join-Path $out 'DR_VERIFICATION_PASS.txt') -Encoding UTF8
}finally{& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -c "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname='$db';" *> $null;& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -c "DROP DATABASE IF EXISTS \"$db\";" *> $null}
